//! RSA-4096 key operations — sign, verify, encrypt, decrypt, keygen.
//!
//! The RSA-4096 service layer, generated by the same
//! `define_rsa_wide` macro that produces RSA-3072 in [`crate::rsa3072`].
//!
//! # Approved services
//!
//! | Service | Spec | Entry point |
//! |---------|------|-------------|
//! | RSASSA-PKCS1-v1_5 verify, SHA-256 | FIPS 186-5 §5.4 / RFC 8017 §8.2 | [`pkcs1_v15_verify`] |
//! | RSASSA-PKCS1-v1_5 sign, SHA-256   | FIPS 186-5 §5.4 / RFC 8017 §8.2 | [`RsaPrivateKey4096::sign_pkcs1_v15_sha256`] |
//! | RSASSA-PSS verify, SHA-256, MGF1  | FIPS 186-5 §5.4 / RFC 8017 §8.1 | [`pss_verify`] |
//! | RSASSA-PSS sign, SHA-256, MGF1    | FIPS 186-5 §5.4 / RFC 8017 §8.1 | [`RsaPrivateKey4096::sign_pss_sha256_with_salt`] |
//! | RSA key generation (4096-bit)     | FIPS 186-5 §A.1.1 / §B.3.1      | [`RsaPrivateKey4096::generate`] |
//! | RSAES-OAEP encrypt, SHA-256       | SP 800-56Br2 / RFC 8017 §7.1    | [`oaep_encrypt`] |
//! | RSAES-OAEP decrypt, SHA-256       | SP 800-56Br2 / RFC 8017 §7.1    | [`RsaPrivateKey4096::decrypt_oaep_sha256`] |
//!
//! # PSS parameters
//!
//! `emBits = 4095`, `emLen = 512`, `sLen = hLen = 32`.
//!
//! # OAEP parameters
//!
//! `k = 512`, `hLen = 32`, `DB_LEN = 479`, `MAX_MSG_LEN = 446`.
//!
//! # Side-channel posture
//!
//! Identical to RSA-2048 / RSA-3072 — `pow_secret` uses the
//! constant-time 4-bit windowed Montgomery ladder at half-width
//! (`MontCtx2048`) and full-width (`MontCtx4096`). Constant time at
//! full width is unproven: no timing probe covers `MontCtx4096`.

#![allow(
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::cast_possible_truncation,
    clippy::similar_names,
    clippy::too_many_arguments,
    dead_code
)]

use crate::bigint2048::U2048;
use crate::bigint4096::U4096;
use crate::mont2048::MontCtx2048;
use crate::mont4096::MontCtx4096;

crate::rsa_wide_impl::define_rsa_wide! {
    full_type = U4096;
    full_bytes = 512;
    full_limbs = 64;
    full_mont = MontCtx4096;
    full_mod = crate::bigint4096;
    half_type = U2048;
    half_bytes = 256;
    half_limbs = 32;
    half_mont = MontCtx2048;
    half_reduce = crate::keygen4096::u4096_mod_u2048;
    keygen_fn = crate::keygen4096::generate_4096_internal;
    keygen_km = KeyMaterial4096;
    nlen = 4096;
    em_bits = 4095;
    em_len = 512;
    oaep_k = 512;
    oaep_max_msg = 446;
    rbg_strength = crate::RSA_4096_RBG_STRENGTH_BITS;
    key_struct = RsaPrivateKey4096;
    crt_struct = CrtComponents4096;
    crt_raw = CrtComponentsRaw4096;
    svc_keygen = Service::RsaKeygen4096;
    svc_pkcs1_sign = Service::RsaPkcs1v15Sign4096;
    svc_pkcs1_verify = Service::RsaPkcs1v15Verify4096;
    svc_pss_sign = Service::RsaPssSign4096;
    svc_pss_verify = Service::RsaPssVerify4096;
    svc_oaep = Service::RsaOaep4096;
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::panic, clippy::expect_used)]
mod tests {
    use super::*;
    use oxicrypt_drbg::HmacDrbgSha256;
    use oxicrypt_module::Rbg;

    /// Stands in for the pre-operational integrity test.
    ///
    /// A `cargo test` binary is never signed, so the real integrity test
    /// cannot pass inside one. The module requires an integrity group to
    /// initialise at all, so a test that needs a gated service declares
    /// this stub — visibly, at the call site — rather than the module
    /// offering any way to skip the requirement.
    const UNSIGNED_TEST_BINARY: &[oxicrypt_module::KatEntry] = &[oxicrypt_module::KatEntry {
        name: "integrity not verifiable in an unsigned test binary",
        run: || Ok(()),
    }];

    fn init_module() {
        let _ = oxicrypt_module::initialize_with_tests(UNSIGNED_TEST_BINARY, &[]);
    }

    #[test]
    fn pkcs1_v15_sign_verify_roundtrip() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-test").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let msg = b"rsa-4096 pkcs1v15 roundtrip";
        let sig = key.sign_pkcs1_v15_sha256(msg).unwrap();
        pkcs1_v15_verify(
            key.modulus_bytes().unwrap(),
            key.public_exponent().unwrap(),
            msg,
            &sig,
        )
        .unwrap();
    }

    #[test]
    fn pkcs1_v15_verify_rejects_tampered_sig() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-tamper").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let msg = b"tamper test 4096";
        let mut sig = key.sign_pkcs1_v15_sha256(msg).unwrap();
        sig[200] ^= 0x01;
        assert!(
            pkcs1_v15_verify(
                key.modulus_bytes().unwrap(),
                key.public_exponent().unwrap(),
                msg,
                &sig
            )
            .is_err()
        );
    }

    #[test]
    fn pss_sign_verify_roundtrip() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-pss").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let msg = b"rsa-4096 pss roundtrip";
        let salt = [0x88u8; 32];
        let sig = key.sign_pss_sha256_with_salt(msg, &salt).unwrap();
        pss_verify(
            key.modulus_bytes().unwrap(),
            key.public_exponent().unwrap(),
            msg,
            &sig,
        )
        .unwrap();
    }

    #[test]
    fn pss_verify_rejects_wrong_msg() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-pss-bad").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let salt = [0x44u8; 32];
        let sig = key.sign_pss_sha256_with_salt(b"original", &salt).unwrap();
        assert!(
            pss_verify(
                key.modulus_bytes().unwrap(),
                key.public_exponent().unwrap(),
                b"different",
                &sig
            )
            .is_err()
        );
    }

    #[test]
    fn oaep_encrypt_decrypt_roundtrip() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-oaep").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let label = b"";
        let msg = b"hello OAEP 4096";
        let ct = oaep_encrypt(
            &mut drbg,
            key.modulus_bytes().unwrap(),
            key.public_exponent().unwrap(),
            label,
            msg,
        )
        .unwrap();
        let mut out = [0u8; OAEP_MAX_MSG_LEN];
        let mlen = key.decrypt_oaep_sha256(label, &ct, &mut out).unwrap();
        assert_eq!(&out[..mlen], msg);
    }

    #[test]
    fn oaep_rejects_wrong_label() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-oaep-bad").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let ct = oaep_encrypt(
            &mut drbg,
            key.modulus_bytes().unwrap(),
            key.public_exponent().unwrap(),
            b"right",
            b"msg",
        )
        .unwrap();
        let mut out = [0u8; OAEP_MAX_MSG_LEN];
        assert!(key.decrypt_oaep_sha256(b"wrong", &ct, &mut out).is_err());
    }

    #[test]
    fn from_components_pct_catches_mismatch() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-import-pct").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        assert!(RsaPrivateKey4096::from_components(&key.n_bytes, key.e, &key.d_bytes).is_ok());
        let mut bad_d = key.d_bytes;
        bad_d[MODULUS_BYTES - 1] ^= 0x01;
        let imported = RsaPrivateKey4096::from_components(&key.n_bytes, key.e, &bad_d);
        assert_eq!(imported.err(), Some(oxicrypt_module::Error::InvalidInput));
        assert!(oxicrypt_module::is_operational());
    }

    #[test]
    fn crt_pairwise_consistency_rejects_a_foreign_modulus() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = HmacDrbgSha256::instantiate_from_module(b"rsa4096-crt-pct").unwrap();
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        assert_eq!(key.crt_pairwise_consistency(), Ok(true));

        // Full-width and odd, so only the arithmetic of the test refuses it.
        let mut foreign = key.clone();
        foreign.n_bytes[0] ^= 0x01;
        assert_eq!(foreign.crt_pairwise_consistency(), Ok(false));

        let crt = key.crt.as_ref().unwrap();
        let imported = RsaPrivateKey4096::from_components_crt(
            &foreign.n_bytes,
            key.e,
            &key.d_bytes,
            &crt.p_bytes,
            &crt.q_bytes,
            &crt.dp_bytes,
            &crt.dq_bytes,
            &crt.qinv_bytes,
        );
        assert_eq!(imported.err(), Some(oxicrypt_module::Error::InvalidInput));
        assert!(oxicrypt_module::is_operational());
    }

    #[test]
    fn rbg_below_192_bits_is_refused_by_every_drawing_entry_before_drawing() {
        use crate::test_support::ReportsStrength;
        crate::test_support::start_module();
        init_module();
        let mut strong = HmacDrbgSha256::instantiate_from_module(b"rsa4096-strong").unwrap();
        let key = RsaPrivateKey4096::generate(&mut strong, 65537).unwrap();
        let drew = Error::Rbg(oxicrypt_module::RbgError::Uninstantiated);
        for (bits, expected) in [(191, Error::RbgTooWeak), (192, drew)] {
            assert_eq!(
                RsaPrivateKey4096::generate(&mut ReportsStrength(bits), 65537).err(),
                Some(expected)
            );
            assert_eq!(
                key.sign_pss_sha256(&mut ReportsStrength(bits), b"rsa4096 refusal"),
                Err(expected)
            );
            assert_eq!(
                oaep_encrypt(
                    &mut ReportsStrength(bits),
                    key.modulus_bytes().unwrap(),
                    key.public_exponent().unwrap(),
                    b"",
                    b"rsa4096 refusal",
                ),
                Err(expected)
            );
        }
    }

    #[test]
    fn rbg_at_256_bits_passes_every_drawing_entry() {
        crate::test_support::start_module();
        init_module();
        let mut drbg = oxicrypt_drbg::CtrDrbgAes256::instantiate_from_module(b"rsa4096-ctr256")
            .expect("drbg instantiates");
        assert_eq!(drbg.strength_bits(), 256);
        let key = RsaPrivateKey4096::generate(&mut drbg, 65537).unwrap();
        let msg = b"rsa4096 ctr256";
        let sig = key.sign_pss_sha256(&mut drbg, msg).unwrap();
        pss_verify(
            key.modulus_bytes().unwrap(),
            key.public_exponent().unwrap(),
            msg,
            &sig,
        )
        .unwrap();
        let ct = oaep_encrypt(
            &mut drbg,
            key.modulus_bytes().unwrap(),
            key.public_exponent().unwrap(),
            b"",
            msg,
        )
        .unwrap();
        let mut out = [0u8; OAEP_MAX_MSG_LEN];
        let mlen = key.decrypt_oaep_sha256(b"", &ct, &mut out).unwrap();
        assert_eq!(&out[..mlen], msg);
    }
}
